//! Exact path transcription of dashboard-trace.svg's #panelclip grain.
//!
//! Each source path begins at (x,326), advances in 6px y steps and ends
//! with a 3px step at635. The 52 horizontal deltas below preserve its
//! small wander and lower-left sweep; do not replace them with evenly
//! straight strips. Source-material reconstruction remains NK-07; this
//! table reproduces the current reference, including its limitations.
//! Transcribed 2026-09-21. Stroke/clip are applied by the parent module.
use crate::style::{Ink, Prim, Seg};

const fn steps(mut x: f32, offsets: [f32; 52]) -> [Seg; 52] {
    let mut out = [Seg::Line(0.0, 0.0); 52];
    let mut i = 0;
    let mut y = 326.0;
    while i < 52 {
        x += offsets[i];
        y += if i == 51 { 3.0 } else { 6.0 };
        out[i] = Seg::Line(x, y);
        i += 1;
    }
    out
}

macro_rules! strand {
    ($x:expr, [$($dx:expr),*]) => {
        Prim::Path {
            x: $x, y: 326.0, segs: &steps($x, [$($dx),*]),
            fill: None, stroke: Some(Ink::Fixed(super::GRAIN_LINE)),
            width: 0.7, close: false,
        }
    };
}

